// Embedded assets — inlined as base64 data URIs so images always render correctly
// on static hosts (Vercel, etc.) regardless of how the /assets folder is served.
window.__PA_ASSETS = {
  logo: 'data:image/png;base64,',
  founder: 'data:image/jpeg;base64,',
  mapGrey: 'data:image/png;base64,',
  mapOrange: 'data:image/png;base64,',
  heroCommunityOriginal: 'data:image/jpeg;base64,',
  heroCommunity: 'data:image/jpeg;base64,',
  newsletterPhoto: 'data:image/png;base64,',
  volunteerVideoCover: 'data:image/png;base64,',
  getInvolvedPhoto: 'data:image/jpeg;base64,',
  ourWorkPhoto: 'data:image/jpeg;base64,',
  africaCountriesSvg: 'data:image/svg+xml;base64,',
  dottedAfricaSvg: 'data:image/svg+xml;base64,'
};

(function () {
  // Maps the real filename (as used in src="assets/...") to a key in window.__PA_ASSETS
  var FILE_MAP = {
    'logo-header.png': 'logo',
    'founder.jpg': 'founder',
    'africa-map.png': 'mapGrey',
    'africa-map-orange.png': 'mapOrange',
    'hero-community-original.jpg': 'heroCommunityOriginal',
    'hero-community.jpg': 'heroCommunity',
    'newsletter-photo.png': 'newsletterPhoto',
    'volunteer-video-cover.png': 'volunteerVideoCover',
    'get-involved-photo.jpg': 'getInvolvedPhoto',
    'rachuonyo5-1024x652.jpg': 'ourWorkPhoto',
    'africa-countries.svg': 'africaCountriesSvg',
    'dotted-africa.svg': 'dottedAfricaSvg'
  };

  function basename(url) {
    if (!url) return '';
    return url.split('#')[0].split('?')[0].split('/').pop();
  }

  function dataFor(url) {
    var A = window.__PA_ASSETS;
    var key = FILE_MAP[basename(url)];
    return (key && A[key]) ? A[key] : null;
  }

  function swapImgSrc() {
    document.querySelectorAll('img[src]').forEach(function (img) {
      var d = dataFor(img.getAttribute('src'));
      if (d) img.setAttribute('src', d);
    });
  }

  function swapInlineSvgImages() {
    document.querySelectorAll('image').forEach(function (el) {
      var href = el.getAttribute('href') || el.getAttribute('xlink:href');
      var d = dataFor(href);
      if (d) {
        el.setAttribute('href', d);
        el.setAttribute('xlink:href', d);
      }
    });
  }

  function swapInlineStyleUrls() {
    document.querySelectorAll('[style*="assets/"]').forEach(function (el) {
      var s = el.getAttribute('style');
      var out = s.replace(/url\((['"]?)([^'")]*assets\/[^'")]+)\1\)/g, function (match, quote, path) {
        var d = dataFor(path);
        return d ? "url('" + d + "')" : match;
      });
      if (out !== s) el.setAttribute('style', out);
    });
  }

  function injectCssOverrides() {
    var A = window.__PA_ASSETS;
    if (document.getElementById('pa-embedded-assets-style')) return;
    var css =
      ':root{' +
        '--pa-map-grey:url(\'' + A.mapGrey + '\');' +
        '--pa-map-orange:url(\'' + A.mapOrange + '\');' +
      '}' +
      '.ripple-section::before{background-image:url(\'' + A.dottedAfricaSvg + '\') !important;}' +
      '.stories-section::before{background-image:url(\'' + A.dottedAfricaSvg + '\') !important;}' +
      '.world-map-card .world-map-img{background-image:url(\'' + A.africaCountriesSvg + '\') !important;}';
    var styleTag = document.createElement('style');
    styleTag.id = 'pa-embedded-assets-style';
    styleTag.textContent = css;
    document.head.appendChild(styleTag);
  }

  function apply() {
    if (!window.__PA_ASSETS) return;
    injectCssOverrides();
    swapImgSrc();
    swapInlineSvgImages();
    swapInlineStyleUrls();
  }

  // Expose so other scripts (app.js) can safely re-run this after they
  // inject/replace DOM content, instead of keeping a second, separate map.
  window.PA_applyEmbeddedAssets = apply;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', apply);
  } else {
    apply();
  }
})();
